#!/usr/bin/env pwsh
# Generated by Claude Opus 4.8 (claude.ai/code) · 2026-11-11

<#
.SYNOPSIS
  Backup sequencer — plan, run, and review service backups.
.DESCRIPTION
  Orchestrates per-service backups within a time window, mandatory services
  first, recording events and reporting the result. Services are described in a
  JSON config and implemented by step scripts (recipes or bespoke). See docs/ for
  internals and help/ for usage.
.PARAMETER Command
  plan | run | history | help
.PARAMETER ConfigPath
  Path to config.json. Defaults to the OS config dir (see help/).
.PARAMETER ForceWindow
  Run even when outside the configured time window (manual/test runs).
.PARAMETER ForceAllJobs
  Skip the fit check: attempt every planned job, no deferral (accepts overruns).
.PARAMETER Limit
  history: number of recent runs to show.
.EXAMPLE
  pwsh sequencer.ps1 plan
.EXAMPLE
  pwsh sequencer.ps1 run -ConfigPath ./config.json -ForceWindow -ForceAllJobs
#>

[CmdletBinding()]
param(
    [Parameter(Position = 0)][string]$Command = 'help',
    [string]$ConfigPath,
    [switch]$ForceWindow,
    [switch]$ForceAllJobs,
    [int]$Limit = 20,
    [switch]$Help
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$BaseDir = $PSScriptRoot
Import-Module (Join-Path $BaseDir 'lib/BackupCommon.psm1') -Force

function Get-ConfigDir {
    if ($env:BACKUP_SEQUENCER_CONFIG_DIR) { return $env:BACKUP_SEQUENCER_CONFIG_DIR }
    if ($IsWindows) { return (Join-Path $env:ProgramData 'backup-sequencer') }
    return '/etc/backup-sequencer'
}

function Get-VarDir {
    if ($env:BACKUP_SEQUENCER_VAR_DIR) { return $env:BACKUP_SEQUENCER_VAR_DIR }
    if ($IsWindows) { return (Join-Path (Join-Path $env:ProgramData 'backup-sequencer') 'var') }
    return '/var/lib/backup-sequencer'
}

function Get-SpoolDefault {
    # transient backups awaiting archive -> /var/spool (FHS: data awaiting processing)
    if ($env:BACKUP_SEQUENCER_SPOOL_DIR) { return $env:BACKUP_SEQUENCER_SPOOL_DIR }
    if ($IsWindows) { return (Join-Path (Join-Path $env:ProgramData 'backup-sequencer') 'spool') }
    return '/var/spool/backup-sequencer'
}

function Format-DisplayTime {
    # ConvertFrom-Json parses the ISO ts into [datetime]; render it back as ISO
    # 8601 explicitly so output doesn't follow the pwsh culture (e.g. US 12h).
    param($Ts)
    if ($null -eq $Ts -or "$Ts" -eq '') { return 'never' }
    try { return ([datetime]$Ts).ToString('yyyy-MM-ddTHH:mm:sszzz') }
    catch { return [string]$Ts }
}

function Show-Usage {
    @'
backup sequencer

Usage:
  pwsh sequencer.ps1 <command> [-ConfigPath <path>] [-ForceWindow] [-ForceAllJobs] [-Limit <n>]

Commands:
  plan      Show the ordered plan for the current window (no side effects)
  run       Execute the plan
  history   Show recent run summaries (newest first)
  help      This message

Config resolution (unless -ConfigPath is given):
  Linux:    /etc/backup-sequencer/config.json
  Windows:  %ProgramData%\backup-sequencer\config.json
'@ | Write-Host
}

if ($Help -or $Command -eq 'help') {
    Show-Usage
    return
}

if (-not $ConfigPath) {
    $ConfigPath = Join-Path (Get-ConfigDir) 'config.json'
}
if (-not (Test-Path -LiteralPath $ConfigPath)) {
    Write-Error "Config not found: $ConfigPath"
    return
}
$Config = Get-Content -LiteralPath $ConfigPath -Raw | ConvertFrom-Json

$VarDir = Get-VarDir
$SpoolRoot = Get-SpoolDefault
if ((Test-HasProp $Config 'spool') -and $Config.spool) {
    $SpoolRoot = $Config.spool
}
$Paths = @{
    BaseDir    = $BaseDir
    EventsPath = Join-Path $VarDir 'events.jsonl'
    LockPath   = Join-Path $VarDir 'sequencer.lock'
    SpoolRoot  = $SpoolRoot
}

switch ($Command) {
    'plan' {
        $projection = Get-ServiceProjection -EventsPath $Paths.EventsPath
        $planNow = Get-Date
        $overdueByService = @{}
        foreach ($name in $Config.services.PSObject.Properties.Name) {
            if (-not ((Test-HasProp $Config.services.$name 'enabled') -and [bool]$Config.services.$name.enabled)) { continue }
            $od = Get-ServiceOverdue -Config $Config -Service $name -BaseDir $Paths.BaseDir -EventsPath $Paths.EventsPath -At $planNow
            if ($null -ne $od) { $overdueByService[$name] = $od }
        }
        $plan = Get-BackupPlan -Config $Config -Projection $projection -At $planNow -OverdueByService $overdueByService
        Write-Host ("Plan  window={0}-{1}  (within window now: {2})  [* = mandatory, by score; <1 = covered]" -f `
                $Config.window.open, $Config.window.close, (Test-WithinWindow $Config.window.open $Config.window.close))
        foreach ($plannedJob in $plan) {
            $flag = if ($plannedJob.Mandatory) { '*' } else { ' ' }
            $lastSuccess = Format-DisplayTime $plannedJob.LastSuccess
            $overdue = if ($plannedJob.Overdue -ge 1e6) { 'new' } else { ('x{0:N1}' -f $plannedJob.Overdue) }
            $covered = if ($plannedJob.Overdue -lt 1) { ' covered' } else { '' }
            Write-Host ("  {0} {1,-22} est={2,6:N0}s  overdue={3,-5}  score={4,7:N2}  last={5}{6}" -f `
                    $flag, $plannedJob.Service, $plannedJob.EstimatedSeconds, $overdue, $plannedJob.Score, $lastSuccess, $covered)
        }
    }
    'run' {
        # the engine narrates the run live; here we only send the email report
        $runId = Invoke-BackupRun -Config $Config -Paths $Paths -ForceWindow:$ForceWindow -ForceAllJobs:$ForceAllJobs -InformationAction Continue
        if ($runId -and (Test-HasProp $Config 'notify') -and $Config.notify.enabled) {
            $report = Format-RunReport -EventsPath $Paths.EventsPath -RunId $runId
            Send-BackupReport -Notify $Config.notify -Subject "backup report $runId" `
                -Body $report -BaseDir (Get-ConfigDir) | Out-Null
        }
    }
    'history' {
        $events = Get-BackupEvents -EventsPath $Paths.EventsPath
        $runEnds = @($events | Where-Object { $_.type -eq 'run.end' })
        $recent = @($runEnds | Select-Object -Last $Limit)
        [array]::Reverse($recent)
        foreach ($r in $recent) {
            $svcs = @($events |
                    Where-Object { $_.type -eq 'service.end' -and (Test-HasProp $_ 'runId') -and $_.runId -eq $r.runId } |
                    ForEach-Object { "{0}:{1}" -f $_.svc, $_.status })
            $svcStr = if ($svcs.Count) { $svcs -join ' ' } else { '(nothing run)' }
            Write-Host ("{0}  ok={1} failed={2} planned={3}  [{4}]" -f (Format-DisplayTime $r.ts), $r.summary.ok, $r.summary.failed, $r.summary.planned, $svcStr)
        }
    }
    default {
        Write-Host "Unknown command: $Command"
        Show-Usage
    }
}
